import json, sys
try:
    d = json.load(sys.stdin)
    print(json.dumps({k: v for k, v in d.items() if k != 'data'}, indent=2)[:500])
    if 'data' in d and isinstance(d['data'], list):
        for item in d['data'][:30]:
            name = item.get('variable_name', item.get('name', '?'))
            status = item.get('status', item.get('present', '?'))
            src = item.get('source', item.get('credentialSource', '?'))
            print(f'  {name}: status={status} source={src}')
    elif 'data' in d and isinstance(d['data'], dict):
        for k, v in list(d['data'].items())[:30]:
            if isinstance(v, dict):
                print(f'  {k}: {json.dumps(v)[:120]}')
            else:
                print(f'  {k}: {v}')
except:
    print(sys.stdin.read()[:500])
" 2>&1 | head -60

